const crypto = require('crypto');
const account = $env.PROTRACK_ACCOUNT;
const password = $env.PROTRACK_PASSWORD;
const time = Math.floor(Date.now()/1000).toString();
const md5pass = crypto.createHash('md5').update(password).digest('hex');
const signature = crypto.createHash('md5').update(md5pass+time).digest('hex');
const d = $input.first().json;
return [{ json: { pt_account: account, pt_time: time, pt_signature: signature, conta: d.conta, acao: d.acao } }];

const login = $input.first().json;
const dados = $('Dados (edite aqui)').first().json;
const endpoint = dados.acao === 'bloquear' ? 'block' : 'unblock';
return [{ json: {
  url: `https://api.protrack365.com/api/user/${endpoint}`,
  access_token: login.record ? login.record.access_token : null,
  conta: dados.conta,
  acao: dados.acao
} }];

const r = $input.first().json;
if (r.code === 10012) $getWorkflowStaticData('global').pt_token = null;
let sucesso = false;
let mensagem;

if (r.error) {
  const erro = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  mensagem = /timeout/i.test(erro)
    ? 'Timeout: a Protrack demorou demais pra responder. Tente novamente em instantes.'
    : 'Falha de conexão com a Protrack: ' + erro;
} else if (r.code === 0) {
  sucesso = true;
  mensagem = 'Operação realizada com sucesso.';
} else if (r.code === 10007) {
  mensagem = 'Conta não encontrada na Protrack (identificador errado — pode não ser o CPF, confira o usuário customizado).';
} else if (r.code === 10009) {
  mensagem = 'Limite de requisições da Protrack (TPS) excedido. Aguarde alguns segundos e tente de novo.';
} else if (r.code === 10012) {
  mensagem = 'Token de acesso inválido ou expirado (pode ter sido invalidado por outro login simultâneo).';
} else if (r.code === 10014) {
  mensagem = 'Erro de horário: relógio do servidor dessincronizado com a Protrack.';
} else {
  mensagem = r.message || JSON.stringify(r);
}

return [{ json: { sucesso, codigo: r.code ?? null, mensagem } }];

const r = $input.first().json;
let mensagem;

if (r.error) {
  const erro = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  mensagem = /timeout/i.test(erro)
    ? 'Timeout: a Protrack demorou demais pra responder no login. Tente novamente em instantes.'
    : 'Falha de conexão ao fazer login na Protrack: ' + erro;
} else if (r.code === 10009) {
  mensagem = 'Limite de requisições da Protrack (TPS) excedido durante o login. Aguarde alguns segundos e tente de novo.';
} else if (r.code === 10014) {
  mensagem = 'Erro de horário: relógio do servidor dessincronizado com a Protrack.';
} else {
  mensagem = r.message || JSON.stringify(r);
}

return [{ json: { sucesso: false, etapa: 'login', codigo: r.code ?? null, mensagem } }];

const login = $input.first().json;
if (login.code === 0 && login.record) {
  const staticData = $getWorkflowStaticData('global');
  staticData.pt_token = login.record.access_token;
  staticData.pt_expires_at = Date.now() + 90 * 60 * 1000;
}
return [{ json: login }];

const staticData = $getWorkflowStaticData('global');
const agora = Date.now();
const expiraEm = staticData.pt_expires_at || 0;
const temToken = !!staticData.pt_token;
const usar_cache = temToken && expiraEm > agora;

return [{
  json: {
    usar_cache,
    tem_token: temToken,
    expira_em: expiraEm,
    agora,
    minutos_restantes: expiraEm > agora ? Math.round((expiraEm - agora) / 60000) : 0
  }
}];

// Token do cache foi invalidado por outro login (code 10012).
// Limpa o cache e gera assinatura nova para um unico relogin.
const staticData = $getWorkflowStaticData('global');
staticData.pt_token = null;
staticData.pt_expires_at = 0;
