const login = $input.first().json;
const dados = $('Dados (edite aqui)').first().json;
const endpoint = dados.acao === 'bloquear' ? 'block' : 'unblock';
return [{ json: {
  url: `https://api.protrack365.com/api/user/${endpoint}`,
  access_token: login.record ? login.record.access_token : null,
  conta: dados.conta,
  acao: dados.acao
} }];

// Devolve o token que ESTE workflow ja tem em cache, para o fluxo de bloqueio reusar.
// Nao loga, nao chama a Protrack: so le o que esta guardado aqui.
const sd = $getWorkflowStaticData('global');
const agora = Date.now();
const idade = sd.pt_expires_at ? (sd.pt_expires_at - agora) / 60000 : null;
if (sd.pt_token && sd.pt_expires_at && sd.pt_expires_at > agora) {
  return [{ json: { record: { access_token: sd.pt_token },
                    origem: 'painel', minutos_restantes: Math.round(idade) } }];
}
return [{ json: { record: null, origem: 'painel', motivo: 'sem token valido no painel' } }];

